<script setup lang="ts">
import { useRoute,useRouter } from 'vue-router'
import { get,post } from '../api/client'
import type { Preparation,Model } from '../api/types'
import { useQuery } from '../composables/useQuery'
import { useMutation } from '../composables/useMutation'
import { session,allowed } from '../composables/session'
import { date,label,short } from '../api/format'
import PageHeader from '../components/PageHeader.vue'
import Feedback from '../components/Feedback.vue'
import Icon from '../components/Icon.vue'
import JsonView from '../components/JsonView.vue'
import StatusBadge from '../components/StatusBadge.vue'
const route=useRoute(),router=useRouter(),id=String(route.params.id),root=`/projects/${session.project!.id}`,q=useQuery(s=>get<Preparation>(`/api/v1/preparations/${id}`,s),[],5000),op=useMutation()
async function decide(approval:Model<'ApprovalResponse'>,decision:'approve'|'reject'){
 if(!window.confirm(`请确认你已审查当前项目、环境、版本、资源和预算。是否${decision==='approve'?'同意':'拒绝'}此${approval.required_slot==='data'?'数据':'安全'}审批？`))return
 q.invalidate();await op.run(async()=>{const current=await get<Model<'ApprovalResponse'>>(`/api/v1/approval-requests/${approval.id}`);if(current.data.revision!==approval.revision)throw new Error('审批事实已变化，请刷新后重新审查');return post(`/api/v1/approval-requests/${approval.id}/decisions`,{decision},{etag:current.etag})},'审批决定已记录。');await q.refresh()
}
async function commit(){const p=q.data.value?.preparation;if(route.query.rerunOf||!p||!window.confirm(`确认提交 ${label(p.purpose)}？环境 ${p.environment}，版本 ${short(p.version_id)}。提交不代表作业已经完成。`))return;q.invalidate();const r=await op.run(()=>post<Model<'CommitAcceptedResponse'>>(`/api/v1/preparations/${id}/commit`,{expected_input_fingerprint:p.input_fingerprint},{key:crypto.randomUUID()}));if(r)await router.push(`${root}/runs/${r.data.execution_run_id}`);else await q.refresh()}
</script>
<template><PageHeader eyebrow="FROZEN FACTS, EXPLICIT DECISIONS" title="准备单详情" description="核对同一份事实快照，再做明确的审批与提交。"><button class="button" @click="q.refresh()"><Icon name="refresh" :size="15"/>核实最新状态</button></PageHeader><Feedback :error="q.error.value||op.error.value" :notice="op.notice.value" :loading="q.loading.value" :unknown="op.unknown.value" @retry="q.refresh()"/><template v-if="q.data.value"><div class="detail-grid"><div class="stack"><section class="card"><div class="card-heading"><div><h2>{{label(q.data.value.preparation.purpose)}}</h2><p>{{q.data.value.preparation.id}}</p></div><StatusBadge :value="q.data.value.validity"/></div><div class="card-body"><dl class="fact-list"><div v-for="fact in [['申请环境',q.data.value.preparation.environment],['风险等级',q.data.value.preparation.risk_level],['数据分级',q.data.value.preparation.data_classification],['申请主体',q.data.value.preparation.maker_id],['过期时刻',date(q.data.value.preparation.expires_at)]]" :key="String(fact[0])" class="fact"><dt>{{fact[0]}}</dt><dd>{{fact[1]}}</dd></div><div class="fact"><dt>版本</dt><dd><RouterLink :to="`${root}/versions/${q.data.value.preparation.version_id}`" class="link-arrow">{{short(q.data.value.preparation.version_id,16)}} ↗</RouterLink></dd></div><div class="fact"><dt>冻结输入指纹</dt><dd><code>{{q.data.value.preparation.input_fingerprint}}</code></dd></div></dl><p class="block-note">{{q.data.value.preparation.impact_summary}}</p></div></section><section class="card"><div class="card-heading"><h2>独立职责审批</h2></div><div class="card-body approval-grid"><article v-for="approval in q.data.value.approvals" :key="approval.id" class="approval-card"><header><h3>{{approval.required_slot==='data'?'数据审查':'安全审查'}}</h3><Icon name="shield" :size="18"/></header><StatusBadge :value="approval.status"/><p>审批主体：{{approval.approver_id?short(approval.approver_id,12):'尚未具名决定'}}</p><p>{{date(approval.decided_at)}}</p><div v-if="approval.status==='pending'" class="actions"><button class="button primary small" :disabled="!allowed(`approve_${approval.required_slot}`,q.data.value.available_actions)||op.busy.value||op.unknown.value" @click="decide(approval,'approve')">同意</button><button class="button danger small" :disabled="!allowed(`approve_${approval.required_slot}`,q.data.value.available_actions)||op.busy.value||op.unknown.value" @click="decide(approval,'reject')">拒绝</button></div></article></div></section><section class="card"><div class="card-heading"><h2>精确资源与输入绑定</h2></div><div class="card-body"><JsonView :value="q.data.value.preparation.resource_scopes"/><details class="section-space"><summary>查看 Schema / Secret 版本绑定</summary><JsonView :value="q.data.value.preparation.input_bindings" class="section-space"/></details></div></section></div><div class="stack"><section class="card"><div class="card-heading"><h2>运行预算</h2></div><div class="card-body"><JsonView :value="q.data.value.preparation.supervision_contract"/></div></section><section class="card"><div class="card-heading"><h2>质量与回滚范围</h2></div><div class="card-body"><details><summary>质量契约</summary><JsonView :value="q.data.value.preparation.quality_contract" class="section-space"/></details><details class="section-space"><summary>回滚计划</summary><JsonView :value="q.data.value.preparation.rollback_plan" class="section-space"/></details></div></section><section class="card model-card"><h2>申请、批准与执行相互独立</h2><p>按钮可用仅是展示控制。后端在提交和首次消费时仍会重新验证审批与指纹。</p><RouterLink v-if="typeof route.query.rerunOf==='string'" :to="`${root}/runs/${encodeURIComponent(route.query.rerunOf)}?preparation=${id}&amp;intent=rerun`" class="button">返回原运行提交安全重跑</RouterLink><template v-else-if="['execute_etl','isolated_trial'].includes(q.data.value.preparation.purpose)"><button class="button primary" :disabled="!allowed('commit',q.data.value.available_actions)||op.busy.value||op.unknown.value" @click="commit"><Icon name="play" :size="15"/>提交受管执行</button></template><RouterLink v-else-if="q.data.value.preparation.purpose==='rollback'" :to="`${root}/runs/${q.data.value.preparation.execution_run_id}?preparation=${id}`" class="button">返回原运行提交回滚</RouterLink><RouterLink v-else :to="`${root}/governance/benchmarks?preparation=${id}`" class="button">返回 L2 评测提交</RouterLink><p v-for="a in (q.data.value.available_actions||[]).filter(a=>!a.allowed&&a.reason_message)" :key="a.action" class="subtle-label">{{a.reason_message}}</p></section></div></div></template></template>
